  for (let x = -1800; x <= 1800; x += 110) {
    if (Math.abs(x - 400) < 60) continue;
    lamps.push({ x, z: CANAL.z0 - 8, h: 10 });
  }
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    lamps.push({ x: 400 + Math.cos(a) * 150, z: Math.sin(a) * 150, h: 10 });
