  boats.push({ x: 1780, z: -380, angle: 0.4, s: 1.4 });
  boats.push({ x: 1830, z: -40, angle: -0.3, s: 1.1 });
  boats.push({ x: 1770, z: 330, angle: 1.2, s: 1.6 });
  boats.push({ x: -1000, z: 690, angle: 0, s: 0.9 });
  boats.push({ x: 800, z: 690, angle: 0.1, s: 0.9 });

