  const driveSpots = [
    { x: 330, z: 60, angle: 0.2 }, { x: 470, z: -70, angle: -0.4 },
    { x: 300, z: -100, angle: 0.9 }, { x: 500, z: 110, angle: 2.6 },
    { x: 400, z: -500, angle: 0 }, { x: 400, z: 500, angle: 0 },
    { x: 400, z: -1100, angle: 0 }, { x: 400, z: 1100, angle: 0 },
